report_script:
frappe.ui.form.on('Revenue by Outlet', {
    refresh: function(frm) {
        // Set default dates
        if (!frm.doc.start) frm.set_value('start', frappe.datetime.get_today());
        if (!frm.doc.end) frm.set_value('end', frappe.datetime.get_today());

        // Set default company if not already selected
        if (!frm.doc.company && frappe.boot.user.defaults.company) {
            frm.set_value('company', frappe.boot.user.defaults.company);
        }
    },

    start: function(frm) { frm.reload_doc(); },
    end: function(frm) { frm.reload_doc(); },
    company: function(frm) { frm.reload_doc(); }
});
